import type { SupabaseClient } from '@supabase/supabase-js';
import type { ReceiptInsert, ReceiptRow } from '$lib/models/Receipt';
import { withRetry } from '$lib/utils/retry';
import type { ReceiptExtract } from '$lib/utils/sanitize';
import { isSuspiciousDate } from '$lib/utils/dateValidation';
import { resolveOcrReceiptDate } from '$lib/utils/receiptDateCorrection';
