/**
 * Gate the Source File before we decode it: is this a kind of file we handle,
 * and is it small enough to be worth loading into memory at all?
 *
 * Deliberately says nothing about the 5MB image limit — that limit describes
 * what we store, and this file has not been shrunk yet. See
 * `docs/adr/0006-the-stored-image-is-the-contract.md`.
 */
validateSourceFile(file: File): Validation {
	if ([...IMAGE_TYPES, PDF_TYPE].indexOf(file.type) === -1) {
		return { ok: false, message: 'Unsupported file type. Allowed: JPEG, PNG, HEIC, PDF.' };
	}
	if (megabytes(file) > MAX_SOURCE_MB) {
		return { ok: false, message: `File too large to process. Max ${MAX_SOURCE_MB}MB.` };
	}
	return { ok: true };
}

/**
 * Gate the Receipt Image we are about to store. Reached only after the resize,
 * so an image over the limit here means the shrink did not happen — say that,
 * rather than telling someone their photo is too big when the app's own job
 * was to make it smaller.
 */
validateReceiptImage({ file, shrunk }: PreparedUpload): Validation {
	const sizeMB = megabytes(file);
	if (file.type === PDF_TYPE) {
		return sizeMB > MAX_PDF_MB
			? { ok: false, message: `PDF too large. Max ${MAX_PDF_MB}MB.` }
			: { ok: true };
	}
	if (sizeMB <= MAX_IMAGE_MB) return { ok: true };
	return {
		ok: false,
		message: shrunk
			? `Image too large. Max ${MAX_IMAGE_MB}MB.`
			: `This image could not be shrunk, and the original is over ${MAX_IMAGE_MB}MB. Try a smaller photo.`
	};
}

