async uploadAndCreate(file: File) {
	const source = this.validateSourceFile(file);
	if (!source.ok) throw new Error(source.message);

	// Shrink first, then judge the result. Both steps sit outside withRetry:
	// a rejection here is deterministic, so retrying it would only delay the
	// error, and re-decoding the image on every attempt wastes memory.
	const prepared = await this.prepareFileForUpload(file);
	const artifact = this.validateReceiptImage(prepared);
	if (!artifact.ok) throw new Error(artifact.message);

	return withRetry(async () => {
		const path = await this.uploadToStorage(prepared.file);
		const extract = await this.extractReceiptDataFailSoft(path, prepared.file.type);
		const values = await this.buildReceiptInsert(file, path, extract);
		const data = await this.insertReceiptOrCleanupUpload(values, path);
		await this.autoAssignCategoryBestEffort(data, extract?.merchant_name ?? null);
		return data as ReceiptRow;
	});
}

