65		 * the point where one image pixel fills one CSS pixel. Beyond it the browser
66		 * would only interpolate, so the controls stop there — and for an image
67		 * already at or under viewport size they never leave 100% at all.
68		 */
69		let maxZoom = $derived(400);
70	
71		// Pending scroll adjustment for zoom-to-cursor
