73	
74		// Computed scaled dimensions
75		let scaledWidth = $derived((baseWidth * zoom) / 100);
76		let scaledHeight = $derived((baseHeight * zoom) / 100);
77	
78		/**
79		 * Capture base dimensions on image load — the size the image
80		 * occupies at 100% zoom, fit within the viewport constraints.
81		 */
82		function handleImageLoad(e: Event) {
83			const img = e.target as HTMLImageElement;
84			naturalWidth = img.naturalWidth;
85			const fit = calculateFitDimensions(
