91			baseWidth = fit.width;
92			baseHeight = fit.height;
93		}
94	
95		/**
96		 * #{#zom1a} Zoom to a specific level, optionally anchored at a cursor position.
97		 * The point under the cursor stays fixed on screen after zoom.
98		 */
99		function zoomTo(newZoom: number, cursorX?: number, cursorY?: number) {
100			const container = scrollContainer;
101			newZoom = Math.max(MIN_ZOOM, Math.min(maxZoom, newZoom));
102	
103			if (!container || baseWidth === 0) {
104				zoom = newZoom;
105				return;
106			}
107	
108			const oldZoom = zoom;
109			if (newZoom === oldZoom) return;
110	
111			const rect = container.getBoundingClientRect();
112			// Default to center of viewport if no cursor position given
113			const cx = cursorX !== undefined ? cursorX - rect.left : rect.width / 2;
114			const cy = cursorY !== undefined ? cursorY - rect.top : rect.height / 2;
115	
116			// Point in base-image coordinates under the cursor
117			const imageX = (container.scrollLeft + cx) / (oldZoom / 100);
118			const imageY = (container.scrollTop + cy) / (oldZoom / 100);
119	
120			zoom = newZoom;
121	
122			// After Svelte updates the DOM (image resizes), adjust scroll so the
123			// same image point remains under the cursor.
124			const targetScrollLeft = imageX * (newZoom / 100) - cx;
125			const targetScrollTop = imageY * (newZoom / 100) - cy;
