144	
145		/**
146		 * #{#zom1a} Zoom out by one step (snaps to 50% increments)
147		 */
148		function zoomOut(cursorX?: number, cursorY?: number) {
149			zoomTo(Math.floor((zoom - 1) / ZOOM_STEP) * ZOOM_STEP, cursorX, cursorY);
150		}
151	
152		/**
153		 * #{#zom1a} Reset zoom to 100% and scroll to origin
154		 */
155		function resetZoom() {
156			zoom = MIN_ZOOM;
157			if (scrollContainer) {
158				scrollContainer.scrollLeft = 0;
159				scrollContainer.scrollTop = 0;
160			}
161		}
162	
163		/**
164		 * #{#zom1b} #{#pdf1c} Handle mouse wheel zoom — disabled for PDFs.
165		 * Zooms toward the cursor position.
166		 */
