import type { SupabaseClient } from '@supabase/supabase-js';
import type { ReceiptInsert, ReceiptRow } from '$lib/models/Receipt';
import { withRetry } from '$lib/utils/retry';
import type { ReceiptExtract } from '$lib/utils/sanitize';
import { isSuspiciousDate } from '$lib/utils/dateValidation';
import { resolveOcrReceiptDate } from '$lib/utils/receiptDateCorrection';
import { isResizableImage, resizeImage } from '$lib/utils/imageResize';
import { getSignedReceiptUrl } from '$lib/utils/signedUrl';
import { sanitizeFilename } from '$lib/utils/sanitizeFilename';

const IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/heic'];
const PDF_TYPE = 'application/pdf';

/**
 * What we agree to STORE — these describe the Receipt Image produced by
 * `prepareFileForUpload`, not the Source File a person picked.
 */
const MAX_IMAGE_MB = 5;
const MAX_PDF_MB = 10;

/**
 * What we are willing to DECODE. Purely a memory guard: above this, loading the
 * image to shrink it can wedge or crash the tab, so nothing is gained by trying.
 * It is not a statement about acceptable receipts — a 12MB phone photo is fine.
 */
const MAX_SOURCE_MB = 25;

type Validation = { ok: true } | { ok: false; message: string };

/** The Receipt Image to store, and whether we managed to shrink it. */
type PreparedUpload = { file: File; shrunk: boolean };

const megabytes = (file: File) => file.size / (1024 * 1024);

/** The database row also carries family_id (set by trigger/RLS), which the model omits. */
type InsertedReceiptRow = ReceiptRow & { family_id: string | null };

export class ReceiptService {
	private supabase: SupabaseClient;

