/**
 * Gate the Source File before we decode it: is this a kind of file we handle,
 * and is it small enough to be worth loading into memory at all?
 *
 * Deliberately says nothing about the 5MB image limit — that limit describes
 * what we store, and this file has not been shrunk yet. See
 * `docs/adr/0006-the-stored-image-is-the-contract.md`.
 */
validateSourceFile(file: File): Validation {
	if ([...IMAGE_TYPES, PDF_TYPE].indexOf(file.type) === -1) {
		return { ok: false, message: 'Unsupported file type. Allowed: JPEG, PNG, HEIC, PDF.' };
	}
	if (megabytes(file) > MAX_SOURCE_MB) {
		return { ok: false, message: `File too large to process. Max ${MAX_SOURCE_MB}MB.` };
	}
	return { ok: true };
}

/**
 * Gate the Receipt Image we are about to store. Reached only after the resize,
 * so an image over the limit here means the shrink did not happen — say that,
 * rather than telling someone their photo is too big when the app's own job
 * was to make it smaller.
 */
validateReceiptImage({ file, shrunk }: PreparedUpload): Validation {
	const sizeMB = megabytes(file);
	if (file.type === PDF_TYPE) {
		return sizeMB > MAX_PDF_MB
			? { ok: false, message: `PDF too large. Max ${MAX_PDF_MB}MB.` }
			: { ok: true };
	}
	if (sizeMB <= MAX_IMAGE_MB) return { ok: true };
	return {
		ok: false,
		message: shrunk
			? `Image too large. Max ${MAX_IMAGE_MB}MB.`
			: `This image could not be shrunk, and the original is over ${MAX_IMAGE_MB}MB. Try a smaller photo.`
	};
}

/**
 * Upload a receipt file, extract its data via OCR, and persist the receipt row.
 *
 * Resilience invariants (see upload-pipeline-resilience spec):
 * - OCR is best-effort: any OCR failure still creates the receipt without extracted data.
 * - No orphan storage files: if the insert fails after upload, the blob is removed.
 */
async uploadAndCreate(file: File) {
	const source = this.validateSourceFile(file);
	if (!source.ok) throw new Error(source.message);

	// Shrink first, then judge the result. Both steps sit outside withRetry:
	// a rejection here is deterministic, so retrying it would only delay the
	// error, and re-decoding the image on every attempt wastes memory.
	const prepared = await this.prepareFileForUpload(file);
	const artifact = this.validateReceiptImage(prepared);
	if (!artifact.ok) throw new Error(artifact.message);

	return withRetry(async () => {
		const path = await this.uploadToStorage(prepared.file);
		const extract = await this.extractReceiptDataFailSoft(path, prepared.file.type);
		const values = await this.buildReceiptInsert(file, path, extract);
		const data = await this.insertReceiptOrCleanupUpload(values, path);
		await this.autoAssignCategoryBestEffort(data, extract?.merchant_name ?? null);
		return data as ReceiptRow;
	});
}

