/**
 * `resizeImage` end-to-end, in a real browser.
 *
 * This file carries the `.svelte.spec.ts` suffix purely to reach the Chromium
 * project (see `vite.config.ts` — the `client` project matches that suffix, the
 * `server` project excludes it). It is not a component test. Without it the
 * function's body never executes anywhere: `imageResize.spec.ts` runs in node,
 * where `createImageBitmap` and `document` are both undefined, so it can only
 * ever reach the early return.
 *
 * These assertions are on the produced file itself — its type, name, dimensions
 * and pixels — rather than on the arithmetic, which `imageResize.spec.ts`
 * already pins.
 */
import { describe, it, expect } from 'vitest';
import { MAX_IMAGE_DIMENSION, resizeImage } from './imageResize';

/** Paint an image of a given size and hand it back as a File. */
async function makeImageFile(
	width: number,
	height: number,
	type: 'image/png' | 'image/jpeg',
	paint?: (ctx: CanvasRenderingContext2D) => void
): Promise<File> {
	const canvas = document.createElement('canvas');
	canvas.width = width;
	canvas.height = height;
	const ctx = canvas.getContext('2d')!;
	// Noise, so the encoder cannot cheat a solid colour down to nothing.
	for (let x = 0; x < width; x += 8) {
		ctx.fillStyle = x % 16 === 0 ? '#204080' : '#e0a020';
		ctx.fillRect(x, 0, 8, height);
	}
	paint?.(ctx);
	const blob = await new Promise<Blob>((resolve) =>
		canvas.toBlob((b) => resolve(b!), type, type === 'image/jpeg' ? 0.95 : undefined)
	);
	return new File([blob], `receipt.${type === 'image/png' ? 'png' : 'jpg'}`, { type });
}

/** Decode a produced file so its real dimensions can be asserted. */
async function dimensionsOf(file: File): Promise<{ width: number; height: number }> {
	const bitmap = await createImageBitmap(file);
	const { width, height } = bitmap;
	bitmap.close();
	return { width, height };
}

/** The colour at a pixel of a produced file. */
async function pixelAt(file: File, x: number, y: number): Promise<[number, number, number, number]> {
	const bitmap = await createImageBitmap(file);
	const canvas = document.createElement('canvas');
	canvas.width = bitmap.width;
	canvas.height = bitmap.height;
	const ctx = canvas.getContext('2d')!;
	ctx.drawImage(bitmap, 0, 0);
	bitmap.close();
	const [r, g, b, a] = ctx.getImageData(x, y, 1, 1).data;
	return [r, g, b, a];
}

describe('resizeImage in the browser', () => {
	it('turns a PNG into a JPEG named .jpg', async () => {
		const source = await makeImageFile(600, 400, 'image/png');

		const result = await resizeImage(source);

		expect(result.type).toBe('image/jpeg');
		expect(result.name).toBe('receipt.jpg');
	});

	it('caps the longest axis at the pixel budget, preserving aspect ratio', async () => {
		// Portrait, well over budget on the long axis — a receipt photographed whole.
		const source = await makeImageFile(1800, 3600, 'image/jpeg');

		const { width, height } = await dimensionsOf(await resizeImage(source));

		expect(height).toBe(MAX_IMAGE_DIMENSION);
		expect(width).toBe(MAX_IMAGE_DIMENSION / 2);
	});

	it('leaves dimensions alone when the image is already within budget', async () => {
		const source = await makeImageFile(800, 600, 'image/jpeg');

		expect(await dimensionsOf(await resizeImage(source))).toEqual({ width: 800, height: 600 });
	});

	it('produces a smaller file than it was given', async () => {
		const source = await makeImageFile(3000, 2000, 'image/png');

		const result = await resizeImage(source);

		expect(result.size).toBeLessThan(source.size);
	});

	it('puts a transparent PNG on white, not on black', async () => {
		// A screenshot of an e-receipt: dark text, no background. JPEG has no alpha,
		// and an uncomposited canvas is transparent BLACK — so getting this wrong
		// stores black-on-black, and the transcode is the only copy we keep.
		const canvas = document.createElement('canvas');
		canvas.width = 400;
		canvas.height = 300;
		const ctx = canvas.getContext('2d')!;
		ctx.clearRect(0, 0, 400, 300); // fully transparent
		const blob = await new Promise<Blob>((resolve) =>
			canvas.toBlob((b) => resolve(b!), 'image/png')
		);
		const transparent = new File([blob], 'e-receipt.png', { type: 'image/png' });

		const [r, g, b] = await pixelAt(await resizeImage(transparent), 200, 150);

		expect(r).toBeGreaterThan(240);
		expect(g).toBeGreaterThan(240);
		expect(b).toBeGreaterThan(240);
	});

	it('returns a PDF untouched', async () => {
		const pdf = new File(['%PDF-1.4'], 'statement.pdf', { type: 'application/pdf' });

		expect(await resizeImage(pdf)).toBe(pdf);
	});
});

