		const source = await makeImageFile(800, 600, 'image/jpeg');

		expect(await dimensionsOf(await resizeImage(source))).toEqual({ width: 800, height: 600 });
	});

	it('produces a smaller file than it was given', async () => {
		const source = await makeImageFile(3000, 2000, 'image/png');

		const result = await resizeImage(source);

		expect(result.size).toBeLessThan(source.size);
	});

