/**
 * Test Suite for Receipt Image Resizing
 *
 * `resizeImage` itself needs Canvas and runs only in a browser, so what is
 * covered here are the decisions it delegates: the target dimensions, which
 * Source File types are worth decoding, and the name the resulting Receipt
 * Image carries. See `docs/adr/0006-the-stored-image-is-the-contract.md`.
 */

import { describe, it, expect } from 'vitest';
import {
	MAX_IMAGE_DIMENSION,
	calculateResizeDimensions,
	isResizableImage,
	toJpegFilename,
	resizeImage
} from './imageResize';

describe('Receipt Image Resizing', () => {
	describe('calculateResizeDimensions', () => {
		it('should preserve dimensions if image is smaller than max size', () => {
			const result = calculateResizeDimensions(1000, 800, 2000);
			expect(result).toEqual({ width: 1000, height: 800 });
		});

		it('should preserve dimensions for exactly 2000px image', () => {
			const result = calculateResizeDimensions(2000, 1500, 2000);
			expect(result).toEqual({ width: 2000, height: 1500 });
		});

		it('should resize landscape image with width > 2000px', () => {
			const result = calculateResizeDimensions(3000, 2000, 2000);
			expect(result.width).toBe(2000);
			expect(result.height).toBe(1333);
		});

		it('should resize portrait image with height > 2000px', () => {
			const result = calculateResizeDimensions(2000, 3000, 2000);
			expect(result.width).toBe(1333);
			expect(result.height).toBe(2000);
		});

		it('should resize square image correctly', () => {
			const result = calculateResizeDimensions(4000, 4000, 2000);
			expect(result.width).toBe(2000);
			expect(result.height).toBe(2000);
		});

		it('should maintain aspect ratio for landscape image', () => {
			const result = calculateResizeDimensions(4000, 3000, 2000);
			const originalRatio = 4000 / 3000;
			const newRatio = result.width / result.height;
			expect(Math.abs(originalRatio - newRatio)).toBeLessThan(0.01);
		});

		it('should maintain aspect ratio for portrait image', () => {
			const result = calculateResizeDimensions(3000, 4000, 2000);
			const originalRatio = 3000 / 4000;
			const newRatio = result.width / result.height;
			expect(Math.abs(originalRatio - newRatio)).toBeLessThan(0.01);
		});

		it('should handle very wide panorama images', () => {
			const result = calculateResizeDimensions(6000, 1500, 2000);
			expect(result.width).toBe(2000);
			expect(result.height).toBe(500);
		});

		it('should handle very tall images', () => {
			const result = calculateResizeDimensions(1500, 6000, 2000);
			expect(result.width).toBe(500);
			expect(result.height).toBe(2000);
		});

		it('should default to the 2400px budget when no max size is given', () => {
			const result = calculateResizeDimensions(4800, 3600);
			expect(MAX_IMAGE_DIMENSION).toBe(2400);
			expect(result.width).toBe(2400);
			expect(result.height).toBe(1800);
		});

		it('should allow custom max size parameter', () => {
			const result = calculateResizeDimensions(4000, 3000, 1000);
			expect(result.width).toBe(1000);
			expect(result.height).toBe(750);
		});

		it('should round dimensions to whole pixels', () => {
			const result = calculateResizeDimensions(3000, 2000, 2000);
			expect(Number.isInteger(result.width)).toBe(true);
			expect(Number.isInteger(result.height)).toBe(true);
		});
	});

	describe('isResizableImage', () => {
		it('accepts every image type a person can upload', () => {
			expect(isResizableImage('image/jpeg')).toBe(true);
			expect(isResizableImage('image/png')).toBe(true);
			expect(isResizableImage('image/heic')).toBe(true);
		});

		it('rejects PDFs, which are stored exactly as received', () => {
			expect(isResizableImage('application/pdf')).toBe(false);
		});

		it('rejects image types the upload control never offers', () => {
			expect(isResizableImage('image/webp')).toBe(false);
			expect(isResizableImage('image/gif')).toBe(false);
		});
	});

	describe('toJpegFilename', () => {
		it('rewrites the extension so the stored object is honestly named', () => {
			expect(toJpegFilename('IMG_4821.HEIC')).toBe('IMG_4821.jpg');
			expect(toJpegFilename('screenshot.png')).toBe('screenshot.jpg');
		});

		it('leaves a JPEG name alone apart from normalizing the extension', () => {
			expect(toJpegFilename('receipt.jpeg')).toBe('receipt.jpg');
			expect(toJpegFilename('receipt.jpg')).toBe('receipt.jpg');
		});

		it('appends an extension when the name has none', () => {
			expect(toJpegFilename('receipt')).toBe('receipt.jpg');
		});

		it('only replaces the final extension in a dotted name', () => {
			expect(toJpegFilename('costco.2026-08-01.png')).toBe('costco.2026-08-01.jpg');
		});
	});

	describe('resizeImage - Type Handling', () => {
		it('should return original file for non-image types', async () => {
			const pdfFile = new File(['pdf data'], 'receipt.pdf', { type: 'application/pdf' });
			const result = await resizeImage(pdfFile);
			expect(result).toBe(pdfFile);
		});

		it('should return original file for unsupported image types', async () => {
			const webpFile = new File(['webp data'], 'receipt.webp', { type: 'image/webp' });
			const result = await resizeImage(webpFile);
			expect(result).toBe(webpFile);
		});

		it('should attempt HEIC rather than silently passing it through', async () => {
			// Undecodable bytes outside a browser — the point is that it TRIES, so the
			// caller gets a failure it can report instead of a full-size upload.
			const heicFile = new File(['heic data'], 'receipt.heic', { type: 'image/heic' });
			await expect(resizeImage(heicFile)).rejects.toThrow();
		});
	});
});

