		const onclose = vi.fn();
		const screen = render(ReceiptImageViewer, { ...props, onclose });

		await screen.getByRole('button', { name: 'Close image viewer' }).click();
		expect(onclose).toHaveBeenCalledTimes(1);

		window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
		expect(onclose).toHaveBeenCalledTimes(2);
	});

	it('renders a PDF in an iframe with no zoom controls', async () => {
		const screen = render(ReceiptImageViewer, {
			imageUrl: 'http://localhost/receipt.pdf',
			show: true,
			isPdf: true,
			altText: 'Receipt PDF'
		});

		await expect.element(screen.getByTitle('Receipt PDF')).toBeVisible();
		await expect.element(screen.getByRole('button', { name: 'Zoom in' })).not.toBeInTheDocument();
	});
});

