/**
 * Regression corpus for receipt date parsing correction.
 *
 * #{#rdc6a authority=developer} - Regression corpus from sample receipts
 *
 * Each case maps a verbatim printed date + Mistral's interpreted date + an upload date
 * to the expected DateCorrectionResult. Cases are keyed to the real vendor formats in
 * `resources/Sample-Reciepts/` so the parser and correction algorithm are measured, not
 * vibe-checked. Pure data — runs through the pure functions with no network or Mistral.
 *
 * Known vendor formats (see receipt-date-parsing-correction.md):
 *   Costco            YYYY/MM/DD
 *   No Frills/Loblaws YY/MM/DD
 *   Superstore        YY/MM/DD (Loblaw family)
 *   Healthy Planet    YY-MM-DD
 *   City of Kingston  timestamp misread as the year (wrong-token extraction error)
 */

import type { DateCorrectionResult } from './receiptDateCorrection';

