it('refuses an enormous Source File before attempting to decode it', async () => {
	const huge = sourceFile(40, 'panorama.jpg', 'image/jpeg');

	await expect(new ReceiptService(supabase).uploadAndCreate(huge)).rejects.toThrow(/25MB/);

	// The guard exists to protect memory, so it must fire BEFORE the decode.
	expect(resizeImage).not.toHaveBeenCalled();
});

it('accepts a Source File of exactly the decode ceiling', async () => {
	// "Max 25MB" has to mean 25 is allowed, or the message is a lie. Pins `>`
	// against `>=` — the two read identically and differ only here.
	const atLimit = sourceFile(25, 'scan.jpg', 'image/jpeg');

	await expect(new ReceiptService(supabase).uploadAndCreate(atLimit)).resolves.toBeTruthy();
});

it('refuses a Source File a hair over the decode ceiling', async () => {
	const overLimit = sourceFile(25.01, 'scan.jpg', 'image/jpeg');

	await expect(new ReceiptService(supabase).uploadAndCreate(overLimit)).rejects.toThrow(/25MB/);

	expect(resizeImage).not.toHaveBeenCalled();
});

it('accepts a Receipt Image of exactly the stored-image limit', async () => {
	// Same edge on the other gate: pins `<=` against `<`.
	vi.mocked(resizeImage).mockResolvedValue(sourceFile(5, 'IMG_4821.jpg', 'image/jpeg'));
	const photo = sourceFile(18, 'IMG_4821.jpg', 'image/jpeg');

	await expect(new ReceiptService(supabase).uploadAndCreate(photo)).resolves.toBeTruthy();

	expect(upload).toHaveBeenCalledOnce();
});

it('accepts a PDF of exactly its own limit', async () => {
	// The PDF branch selects a different limit, so it needs its own edge.
	const atLimit = sourceFile(10, 'statement.pdf', 'application/pdf');

	await expect(new ReceiptService(supabase).uploadAndCreate(atLimit)).resolves.toBeTruthy();

	expect(upload).toHaveBeenCalledOnce();
});

